// Hard facts (budget, month) are read with rules: vectors are bad at numbers.
// -1 means "no filter".
const item = $input.first().json;
const question = item.chatInput ?? item.question;
const q = question.toLowerCase();

const price = q.match(/(?:under|below|less than|max(?:imum)?|moins de|budget(?: of)?)\s*(\d[\d\s,.]*\d|\d)/);
const max_price = price ? parseInt(price[1].replace(/\D/g, ''), 10) : -1;

const months = {
  january: 1, janvier: 1, february: 2, fevrier: 2, 'février': 2, march: 3, mars: 3,
  april: 4, avril: 4, may: 5, mai: 5, june: 6, juin: 6, july: 7, juillet: 7,
  august: 8, aout: 8, 'août': 8, september: 9, septembre: 9, october: 10, octobre: 10,
  november: 11, novembre: 11, december: 12, decembre: 12, 'décembre': 12,
};
let month = -1;
for (const [name, n] of Object.entries(months)) {
  if (new RegExp(`(^|[^a-zà-ÿ])${name}([^a-zà-ÿ]|$)`).test(q)) { month = n; break; }
}

return [{ json: { question, max_price, month } }];

const question = $('Read filters').first().json.question;

// Label each result [O1], [O2] for offers and [F1], [F2] for FAQ answers
let o = 0, f = 0;
const blocks = [];
for (const item of $input.all()) {
  if (!item.json.text) continue;
  const label = item.json.kind === 'offer' ? `O${++o}` : `F${++f}`;
  blocks.push(`[${label}] ${item.json.text}`);
}

const SYSTEM = "You are the travel assistant of a Tunisian travel agency. Use ONLY the context. " +
  "Each context block starts with its label in brackets, like [O1] for an offer or [F2] for a FAQ answer. " +
  "The offers in the context are the only trips available: never mention other trips, prices or dates. " +
  "If the context gives a rule (deposit, child age, visa, cancellation), apply it to the customer's situation. " +
  "Answer in the customer's language, in 2 to 4 short sentences. " +
  "End with the labels you used, like (source: O1, F2). " +
  "If the context does not answer the question, reply exactly: I don't know. Please contact us on WhatsApp, Monday to Saturday, 9:00 to 18:00.";

return [{ json: {
  model: 'llama3.2:3b',
  stream: false,
  options: { temperature: 0 },
  messages: [
    { role: 'system', content: SYSTEM },
    { role: 'user', content: `Context:\n${blocks.join('\n\n')}\n\nQuestion: ${question}` },
  ],
} }];
